import{_ as l,I as o,g as r,j as t}from"./chunks/framework.CjoWWfVe.js";const h=JSON.parse('{"title":"Модуль «Амбассадор»","description":"Продвижение, генерация умных ссылок, QR-коды на чеках, учет кампаний и ИИ-помощник маркетолога.","frontmatter":{"title":"Модуль «Амбассадор»","description":"Продвижение, генерация умных ссылок, QR-коды на чеках, учет кампаний и ИИ-помощник маркетолога.","order":17},"headers":[],"relativePath":"ru/docs/spaces/ambassador.md","filePath":"ru/docs/spaces/ambassador.md"}'),i={name:"ru/docs/spaces/ambassador.md"};function a(s,e,n,d,g,c){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="🚀-модуль-«амбассадор»-маркетинг-и-партнерство" tabindex="-1">🚀 Модуль «Амбассадор» (Маркетинг и Партнёрство) <a class="header-anchor" href="#🚀-модуль-«амбассадор»-маркетинг-и-партнерство" aria-label="Permalink to &quot;🚀 Модуль «Амбассадор» (Маркетинг и Партнёрство)&quot;">​</a></h1><p><strong>Амбассадор</strong> — это бесплатный системный инструмент, решающий сразу две ключевые задачи мастера и предпринимателя:</p><ol><li><strong>Партнёрский доход в экосистеме ОмниКрафт ЕРП:</strong> Рекомендация программы коллегам с получением бессрочной комиссии и оплатой подписок накопленными баллами.</li><li><strong>Продвижение собственного дела:</strong> Удобный конструктор ссылок, учет рекламных кампаний и встроенный искусственный интеллект для продвижения ваших собственных изделий, цифровых выкроек, обучающих курсов или программ.</li></ol><hr><h2 id="💼-1-вкладка-«кабинет»-персональныи-профиль-быстрые-ссылки-и-центр-ссылок" tabindex="-1">💼 1. Вкладка «Кабинет»: Персональный профиль, быстрые ссылки и центр ссылок <a class="header-anchor" href="#💼-1-вкладка-«кабинет»-персональныи-профиль-быстрые-ссылки-и-центр-ссылок" aria-label="Permalink to &quot;💼 1. Вкладка «Кабинет»: Персональный профиль, быстрые ссылки и центр ссылок&quot;">​</a></h2><p>Вкладка «Кабинет» является главным центром управления амбассадора:</p><ul><li><strong>Реферальный профиль и информационная панель (сводка):</strong> Наглядный статус партнёрства (Партнёр 20%, Мастер 30%, Легенда 50%), персональный код амбассадора, шкала прогресса до следующего уровня и счетчики метрик (клики, продажи за 30 дней, доступный баланс). Нажатием одной кнопки открывается диалог списания заработанных бонусов.</li><li><strong>Генератор быстрых ссылок:</strong> Мгновенное создание персональных ссылок без необходимости заводить отдельную кампанию. Достаточно указать название и выбрать целевую страницу (Главная, Блог, Калькулятор себестоимости, Демо-версия или произвольный адрес) — система автоматически добавит все необходимые параметры.</li><li><strong>Центр всех ссылок (Реестр):</strong> Единый список всех ваших ссылок (как созданных быстро, так и привязанных к кампаниям) с удобным фильтром: <ul><li><em>Все ссылки / ⚡ Быстрые / 📁 Из кампаний;</em></li><li><em>Быстрое копирование:</em> Копирование ссылки в буфер обмена в один клик;</li><li><em>QR-код:</em> Вызов модального окна с крупным QR-кодом для сканирования смартфоном или сохранения;</li><li><em>Привязка к кампании:</em> Любую быструю ссылку можно задним числом привязать к нужной рекламной кампании.</li></ul></li></ul><h3 id="🧾-органическии-рост-водянои-знак-на-электронных-чеках" tabindex="-1">🧾 Органический рост: Водяной знак на электронных чеках <a class="header-anchor" href="#🧾-органическии-рост-водянои-знак-на-электронных-чеках" aria-label="Permalink to &quot;🧾 Органический рост: Водяной знак на электронных чеках&quot;">​</a></h3><p>Включите пункт <strong>«Размещать QR-код на чеках»</strong>, и на каждом электронном чеке при продаже товаров в кассовом терминале будет аккуратно печататься блок с вашим персональным QR-кодом. Передавая чек покупателю, вы органически привлекаете новых пользователей без лишних затрат времени.</p><hr><h2 id="🌐-2-вкладка-«источники»-ии-подбор-площадок-и-библиотека-контактов" tabindex="-1">🌐 2. Вкладка «Источники»: ИИ-подбор площадок и библиотека контактов <a class="header-anchor" href="#🌐-2-вкладка-«источники»-ии-подбор-площадок-и-библиотека-контактов" aria-label="Permalink to &quot;🌐 2. Вкладка «Источники»: ИИ-подбор площадок и библиотека контактов&quot;">​</a></h2><p>Вкладка «Источники» решает задачу поиска целевой аудитории и структурирования каналов продвижения:</p><ul><li><strong>ИИ-подбор площадок (Диалоговый стратег):</strong> Сформулируйте задачу (например, <em>«Где найти кожевников и столяров для калькулятора себестоимости?»</em>), и нейросеть вернет готовые структурированные карточки площадок.</li><li><strong>Карточки-кандидаты:</strong> Для каждого найденного ресурса ИИ формирует карточку с указанием типа (сообщество, форум, статья, видео, реклама), портрета аудитории, правил публикации, тона общения и рекомендуемого интервала между постами.</li><li><strong>Блок «Выбранные кандидаты»:</strong> Отмечайте подходящие площадки кнопкой «Выбрать» — они собираются в верхнюю панель, откуда их можно в один клик сохранить в постоянную библиотеку.</li><li><strong>Библиотека сохранённых источников:</strong> Единая база проверенных ресурсов с поиском, фильтрацией по типам, возможностью архивации и отображением статистики участий в ваших кампаниях (например, <em>«Хабр: 3 кампании, 2 активные»</em>).</li><li><strong>Автономная работа:</strong> Вы можете вручную добавлять, редактировать и вести любые источники даже без настройки API-ключей нейросетей.</li></ul><hr><h2 id="📣-3-вкладка-«кампании»-участия-площадок-контент-и-график-публикации" tabindex="-1">📣 3. Вкладка «Кампании»: Участия площадок, контент и график публикаций <a class="header-anchor" href="#📣-3-вкладка-«кампании»-участия-площадок-контент-и-график-публикации" aria-label="Permalink to &quot;📣 3. Вкладка «Кампании»: Участия площадок, контент и график публикаций&quot;">​</a></h2><p>Вкладка «Кампании» объединяет продвигаемые страницы, выбранные площадки, генерацию промо-материалов и контроль выполнения публикаций:</p><ul><li><strong>Реестр кампаний:</strong> Создавайте кампании с указанием целевой страницы (Главная, Блог, Калькулятор себестоимости, Демо или произвольный адрес), дат проведения, тегов и общих заметок.</li><li><strong>Участия площадок в кампании:</strong> Добавляйте проверенные источники из вашей библиотеки площадок (пакетно или точечно). Для каждого участия настраивается режим (<em>Органика</em> или <em>Платная</em>), выделенный бюджет и контактное лицо.</li><li><strong>Жизненный цикл участия:</strong> Статусы сменяются явно по мере продвижения: <code>Кандидат</code> ➔ <code>В работе</code> ➔ <code>Опубликовано</code> ➔ <code>Завершено</code>.</li><li><strong>Автоматическое рождение ссылки:</strong> При активации участия система автоматически генерирует уникальную реферальную ссылку с точными метками для конкретной пары «Кампания × Площадка» (с кнопками копирования и показа QR-кода).</li><li><strong>Специализированный контент (с учётом площадки):</strong> Встроенный редактор контента учитывает специфику, правила и тон выбранной площадки (пост для сообществ, экспертная статья для блогов, полезный совет для форумов или рекламный питч), поддерживает создание вариантов A/B и защищает от повторов текста.</li><li><strong>Работа без нейросети:</strong> Если API-ключ не настроен, вы можете составлять и сохранять тексты вручную непосредственно в карточке участия.</li><li><strong>«Следующий шаг» (Напоминания):</strong> После фиксации публикации система автоматически рассчитывает дату следующего действия (через 3 дня — проверка статистики кликов и регистраций, либо повторный пост с учетом графика площадки) и подсвечивает актуальные задачи при входе во вкладку.</li><li><strong>Экспорт для внешних помощников (MCP):</strong> В один клик формируется структурированный контекст для передачи автономным цифровым ассистентам.</li></ul><hr><h2 id="📊-4-вкладка-«аналитика»-отчеты-воронка-конверсии-и-экспорт" tabindex="-1">📊 4. Вкладка «Аналитика»: Отчёты, воронка конверсий и экспорт <a class="header-anchor" href="#📊-4-вкладка-«аналитика»-отчеты-воронка-конверсии-и-экспорт" aria-label="Permalink to &quot;📊 4. Вкладка «Аналитика»: Отчёты, воронка конверсий и экспорт&quot;">​</a></h2><p>Вкладка «Аналитика» предоставляет целостную картину эффективности всех ваших маркетинговых активностей и источников:</p><ul><li><strong>Сводные показатели (KPI):</strong> Верхняя панель карточек отражает суммарные клики по ссылкам, количество регистраций, продажи, заработанные бонусы, затраченный рекламный бюджет и среднюю стоимость привлечения клиента (CAC).</li><li><strong>7 аналитических разрезов:</strong><ol><li><em>🎯 Воронка по кампаниям:</em> Показывает путь клиента (Площадки ➔ Клики ➔ Регистрации ➔ Продажи ➔ Доход) с расчетом конверсий на каждом этапе ($CR_1$, $CR_2$, итоговый $CR$).</li><li><em>📊 Сравнение площадок:</em> Сводная таблица по парам «площадка × кампания» с отображением формата, бюджета, кликов, продаж, дохода и прямой ссылки на публикацию.</li><li><em>📑 Разрез по типам площадок:</em> Анализ результативности сообществ, экспертных статей, форумов, видеоканалов и рекламы — наглядно показывает, куда эффективнее направлять усилия.</li><li><em>🏷️ Разрез по тегам:</em> Группировка показателей по целевым сегментам и группам кампаний.</li><li><em>💰 Экономика платных размещений (CAC):</em> Детальный расчет стоимости клика (CPC), стоимости лида (CPA), стоимости клиента ($CAC = \\frac{\\text{Бюджет}}{\\text{Продажи}}$) и чистой окупаемости.</li><li><em>📈 Динамика во времени:</em> График и временной ряд активности по дням для отслеживания затухания эффекта постов и отдачи от повторных публикаций.</li><li><em>🌐 Сводка по продвигаемым страницам:</em> Сравнение отдачи от различных страниц сайта (Главная, Калькулятор себестоимости, Блог, Демо-версия).</li></ol></li><li><strong>Экспорт данных:</strong><ul><li><em>📥 Экспорт в CSV:</em> Выгрузка отчёта в таблицу CSV с кодировкой UTF-8 BOM для корректного открытия в табличных редакторах.</li><li><em>📋 Скопировать отчёт:</em> Копирование структурированного текста отчёта в буфер обмена для быстрой отправки в сообщения или рабочие заметки.</li></ul></li><li><strong>Офлайн-устойчивость:</strong> При отсутствии интернет-соединения все отчёты строятся на локальных снимках метрик с предупреждающим бейджем об автономном режиме.</li></ul><hr><h2 id="🤖-5-автономные-цифровые-помощники-и-протокол-контекста-моделеи-mcp" tabindex="-1">🤖 5. Автономные цифровые помощники и протокол контекста моделей (<code>MCP</code>) <a class="header-anchor" href="#🤖-5-автономные-цифровые-помощники-и-протокол-контекста-моделеи-mcp" aria-label="Permalink to &quot;🤖 5. Автономные цифровые помощники и протокол контекста моделей (`MCP`)&quot;">​</a></h2><p>Модуль поддерживает прямое взаимодействие со сторонними автономными помощниками (<code>Cursor</code>, <code>Antigravity</code>, <code>Claude Desktop</code>) через открытый протокол взаимодействия с моделями (<code>Model Context Protocol</code>):</p><ul><li><strong>Единый каталог инструментов:</strong> Ассистентам доступны безопасные инструменты чтения кампаний (<code>list_campaigns</code>), запроса аналитики (<code>get_stats</code>), создания ссылок (<code>create_link</code>) и генерации контента (<code>generate_content</code>).</li><li><strong>Уровни автономности:</strong> Для каждой площадки настраивается режим работы помощника: <ul><li><em>Черновик:</em> Помощник формирует структуру и ожидает одобрения человека.</li><li><em>Полуавтомат:</em> Публикация одобренного контента с принудительной остановкой при обнаружении защитных проверок и двухфакторного подтверждения входа.</li><li><em>Автопилот:</em> Доступен строго для явно доверенных источников.</li></ul></li><li><strong>Журнал действий (Аудит-лог):</strong> Все вызовы инструментов фиксируются в базе данных с фиксацией времени, статуса и параметров.</li></ul><hr><h2 id="💰-6-партнерская-программа-и-магазин-вознаграждении" tabindex="-1">💰 6. Партнерская программа и Магазин вознаграждений <a class="header-anchor" href="#💰-6-партнерская-программа-и-магазин-вознаграждении" aria-label="Permalink to &quot;💰 6. Партнерская программа и Магазин вознаграждений&quot;">​</a></h2><p>При привлечении коллег в ОмниКрафт ЕРП действует <strong>бессрочная привязка (Lifetime)</strong>: вы получаете процент со всех покупок и продлений привлеченного пользователя.</p><h3 id="шкала-начислении-лестница-милстоунов" tabindex="-1">Шкала начислений (Лестница милстоунов): <a class="header-anchor" href="#шкала-начислении-лестница-милстоунов" aria-label="Permalink to &quot;Шкала начислений (Лестница милстоунов):&quot;">​</a></h3><ul><li>🥉 <strong>Партнёр</strong> (базовый ранг) ➔ Комиссия <strong>20%</strong></li><li>🥈 <strong>Мастер</strong> (от 10 продаж в месяц) ➔ Комиссия <strong>30%</strong></li><li>👑 <strong>Легенда</strong> (от 50 продаж в месяц) ➔ Комиссия <strong>50%</strong></li></ul><h3 id="🎁-использование-баланса" tabindex="-1">🎁 Использование баланса: <a class="header-anchor" href="#🎁-использование-баланса" aria-label="Permalink to &quot;🎁 Использование баланса:&quot;">​</a></h3><p>Накопленные рубли отображаются на информационной панели. Нажав кнопку <em>«Списать бонусы»</em>, вы можете оплатить ими:</p><ul><li>Продление стандартной подписки.</li><li>Бессрочный переход на версию ПРО.</li><li>Покупку специализированных модулей (например, модуля работы с выкройками).</li></ul>',33)])])}const u=l(i,[["render",a]]);export{h as __pageData,u as default};
